#ifndef _WIN32
#include <unistd.h>
#endif
#include <filesystem>
#include <zvec/db/collection.h>
#include <zvec/db/options.h>
#include "zvec/ailego/logger/logger.h"


struct Config {
  std::string path;
};


bool ParseArgs(int argc, char **argv, Config &config) {
  for (int i = 1; i < argc; i++) {
    std::string arg = argv[i];

    if (arg == "--path" && i + 1 < argc) {
      config.path = argv[++i];
    } else if (arg == "--help" || arg == "-h") {
      return false;
    }
  }

  // Validate required arguments
  if (config.path.empty()) {
    return false;
  }

  return true;
}


void PrintUsage(const char *program) {
  std::cout << "Usage: " << program << " --path <collection_path>" << std::endl;
  std::cout << std::endl;
  std::cout << "Arguments:" << std::endl;
  std::cout << "  --path         Path to the collection (required)"
            << std::endl;
}


int main(int argc, char **argv) {
  Config config;

  // Parse arguments
  if (!ParseArgs(argc, argv, config)) {
    PrintUsage(argv[0]);
#ifdef __ANDROID__
    _exit(1);
#endif
    return 1;
  }

  try {
    std::filesystem::path cwd = std::filesystem::current_path();
    std::cout << "[collection_optimizer] Current Working Directory: "
              << cwd.string() << std::endl;
  } catch (const std::filesystem::filesystem_error &e) {
    std::cout << "[collection_optimizer] Failed to get the current working "
                 "directory: "
              << e.what() << std::endl;
  }


